input.command:
echo "=== ls -la .git ===" && ls -la .git && echo "=== find .git -print (no objects content dump) ===" && find .git -print | sort && echo "=== file types ===" && find .git -type f -o -type l | sort | while read -r f; do
  case "$f" in
    .git/objects/pack/*.pack|.git/objects/pack/*.idx) echo "SKIP_BINARY $f" ;;
    *) echo "FILE $f" ;;
  esac
done
